namespace ternet{
bool Value::truthy()const{if(std::holds_alternative<std::monostate>(data))return false;if(auto p=std::get_if<bool>(&data))return *p;if(auto p=std::get_if<std::int64_t>(&data))return *p!=0;if(auto p=std::get_if<double>(&data))return *p!=0;if(auto p=std::get_if<std::string>(&data))return !p->empty();if(auto p=std::get_if<Array>(&data))return !p->empty();if(auto p=std::get_if<Tuple>(&data))return !p->items.empty();if(auto p=std::get_if<Object>(&data))return !p->empty();return true;}
std::string Value::str()const{if(std::holds_alternative<std::monostate>(data))return"null";if(auto p=std::get_if<bool>(&data))return*p?"true":"false";if(auto p=std::get_if<std::int64_t>(&data))return std::to_string(*p);if(auto p=std::get_if<double>(&data)){auto s=std::to_string(*p);while(s.size()>1&&s.back()=='0')s.pop_back();if(!s.empty()&&s.back()=='.')s.pop_back();return s;}if(auto p=std::get_if<std::string>(&data))return*p;if(auto p=std::get_if<Array>(&data)){std::string s="[";for(size_t i=0;i<p->size();++i){if(i)s+=", ";s+=(*p)[i].str();}return s+"]";}if(auto p=std::get_if<Tuple>(&data)){std::string s="(";for(size_t i=0;i<p->items.size();++i){if(i)s+=", ";s+=p->items[i].str();}return s+")";}if(auto p=std::get_if<Object>(&data)){std::string s="{";bool first=true;for(const auto&kv:*p){if(!first)s+=", ";first=false;s+=kv.first+":"+kv.second.str();}return s+"}";}return"<object>";}
Interpreter::Binding*Interpreter::find(const std::string&n){for(auto i=scopes.rbegin();i!=scopes.rend();++i){auto q=i->find(n);if(q!=i->end())return&q->second;}return nullptr;}
const Interpreter::ClassDef*Interpreter::find_class(const std::string&n)const{auto it=classes.find(n);return it==classes.end()?nullptr:&it->second;}
const Interpreter::Function*Interpreter::find_method(const std::string&cls,const std::string&name,std::string*owner)const{std::string cur=cls;while(!cur.empty()){auto it=classes.find(cur);if(it==classes.end())return nullptr;auto m=it->second.methods.find(name);if(m!=it->second.methods.end()){if(owner)*owner=cur;return &m->second;}cur=it->second.parent;}return nullptr;}
Value Interpreter::make_instance(const std::string&name,const std::vector<ExprPtr>&args){auto cls=find_class(name);if(!cls)throw RuntimeError("unknown class '"+name+"'");Value::Object o;o["__class"]=Value(name);std::vector<const ClassDef*> chain;for(auto p=cls;p;p=find_class(p->parent))chain.push_back(p);for(auto it=chain.rbegin();it!=chain.rend();++it)for(const auto&f:(*it)->fields)o[f]=Value{};Value v(std::move(o));if(find_method(name,"init"))return call_method(v,"init",args);if(!args.empty())throw RuntimeError("class '"+name+"' has no constructor");return v;}
Value Interpreter::call_method(const Value&obj,const std::string&name,const std::vector<ExprPtr>&args,const std::string*start_class){auto o=std::get_if<Value::Object>(&obj.data);if(!o)throw RuntimeError("method call requires an object");auto ci=o->find("__class");if(ci==o->end())throw RuntimeError("object has no class");std::string cls=ci->second.str();if(start_class)cls=*start_class;std::string owner;auto fn=find_method(cls,name,&owner);if(!fn)throw RuntimeError("unknown method '"+name+"'");if(fn->params.size()!=args.size())throw RuntimeError("wrong argument count for method '"+name+"'");scopes.push_back({});scopes.back()["this"]={obj,false};auto owner_class=find_class(owner);if(owner_class&&!owner_class->parent.empty()){Value::Object sup=*o;sup["__super_class"]=Value(owner_class->parent);scopes.back()["super"]={Value(std::move(sup)),false};}for(size_t i=0;i<args.size();++i)scopes.back()[fn->params[i]]={eval(args[i]),true};returning=false;return_value={};exec_all(fn->body);auto r=return_value;returning=false;scopes.pop_back();return r;}
Value Interpreter::binary(const std::string&o,const Value&a,const Value&b){if(o=="&&")return a.truthy()&&b.truthy();if(o=="||")return a.truthy()||b.truthy();if(o=="==")return a.str()==b.str();if(o=="!=")return a.str()!=b.str();auto num=[](const Value&v){if(auto p=std::get_if<std::int64_t>(&v.data))return(double)*p;if(auto p=std::get_if<double>(&v.data))return*p;throw RuntimeError("numeric operator requires numbers");};if(o=="+"){if(std::holds_alternative<std::string>(a.data)||std::holds_alternative<std::string>(b.data))return a.str()+b.str();double z=num(a)+num(b);if(std::holds_alternative<std::int64_t>(a.data)&&std::holds_alternative<std::int64_t>(b.data))return Value((std::int64_t)z);return Value(z);}double x=num(a),y=num(b);if(o=="-")return x-y;if(o=="*")return x*y;if(o=="/"){if(y==0)throw RuntimeError("division by zero");return x/y;}if(o=="%")return std::fmod(x,y);if(o==">")return x>y;if(o=="<")return x<y;if(o==">=")return x>=y;if(o=="<=")return x<=y;throw RuntimeError("unknown operator "+o);}
Value Interpreter::eval(const ExprPtr&e){if(!e)throw RuntimeError("internal error: null expression");switch(e->kind){case Expr::Literal:return e->literal;case Expr::Variable:{auto b=find(e->name);if(!b)throw RuntimeError("undefined variable '"+e->name+"'");return b->value;}case Expr::Unary:{auto v=eval(e->right);if(e->op=="!")return!v.truthy();if(e->op=="-"){if(auto p=std::get_if<std::int64_t>(&v.data))return-*p;if(auto p=std::get_if<double>(&v.data))return-*p;}throw RuntimeError("invalid unary operator");}case Expr::Binary:return binary(e->op,eval(e->left),eval(e->right));case Expr::Array:{Value::Array a;for(auto&q:e->args)a.push_back(eval(q));return a;}case Expr::Tuple:{Value::Tuple v;for(auto&q:e->args)v.items.push_back(eval(q));return Value(std::move(v));}case Expr::Index:{auto v=eval(e->left),idx=eval(e->index);auto a=std::get_if<Value::Array>(&v.data);auto n=std::get_if<std::int64_t>(&idx.data);if(!a||!n||*n<0||(size_t)*n>=a->size())throw RuntimeError("array index out of bounds");return(*a)[(size_t)*n];}case Expr::Member:{auto v=eval(e->object);auto o=std::get_if<Value::Object>(&v.data);if(!o)throw RuntimeError("member access requires an object");auto it=o->find(e->name);if(it!=o->end())return it->second;auto ci=o->find("__class");if(ci!=o->end()&&find_method(ci->second.str(),e->name))throw RuntimeError("method '"+e->name+"' must be called");throw RuntimeError("unknown member '"+e->name+"'");}case Expr::Call:{if(e->left->kind==Expr::Member){auto obj=eval(e->left->object);auto oo=std::get_if<Value::Object>(&obj.data);if(!oo)throw RuntimeError("method call requires an object");auto sci=oo->find("__super_class");if(e->left->object->kind==Expr::Variable&&e->left->object->name=="super"&&sci!=oo){std::string parent=sci->second.str();return call_method(obj,e->left->name,e->args,&parent);}return call_method(obj,e->left->name,e->args);}if(e->left->kind!=Expr::Variable)throw RuntimeError("call target must be a function");const auto&name=e->left->name;if(name=="input"||name=="input_string"){if(!e->args.empty())throw RuntimeError(name+" expects no arguments");std::string value;if(!std::getline(std::cin,value))throw RuntimeError("input failed: stdin reached EOF");return Value(value);}if(name=="input_int"){if(!e->args.empty())throw RuntimeError("input_int expects no arguments");std::string value;if(!std::getline(std::cin,value))throw RuntimeError("input_int failed: stdin reached EOF");try{std::size_t used=0;long long n=std::stoll(value,&used);while(used<value.size()&&std::isspace(static_cast<unsigned char>(value[used])))++used;if(used!=value.size())throw std::invalid_argument("trailing input");return Value((std::int64_t)n);}catch(...){throw RuntimeError("input_int: expected an integer");}}if(name=="input_float"){if(!e->args.empty())throw RuntimeError("input_float expects no arguments");std::string value;if(!std::getline(std::cin,value))throw RuntimeError("input_float failed: stdin reached EOF");try{std::size_t used=0;double n=std::stod(value,&used);while(used<value.size()&&std::isspace(static_cast<unsigned char>(value[used])))++used;if(used!=value.size())throw std::invalid_argument("trailing input");return Value(n);}catch(...){throw RuntimeError("input_float: expected a number");}}if(name=="input_bool"){if(!e->args.empty())throw RuntimeError("input_bool expects no arguments");std::string value;if(!std::getline(std::cin,value))throw RuntimeError("input_bool failed: stdin reached EOF");for(char&ch:value)ch=static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));if(value=="true"||value=="1"||value=="yes"||value=="y")return Value(true);if(value=="false"||value=="0"||value=="no"||value=="n")return Value(false);throw RuntimeError("input_bool: expected true/false, yes/no, or 1/0");}if(name=="some"||name=="ok"||name=="err"){if(e->args.size()!=1)throw RuntimeError(name+" expects one value");Value::Object o;o["tag"]=Value(name);o["value"]=eval(e->args[0]);return Value(std::move(o));}if(name=="none"){if(!e->args.empty())throw RuntimeError("none expects no arguments");Value::Object o;o["tag"]=Value("none");return Value(std::move(o));}if(name=="is_some"||name=="is_none"){if(e->args.size()!=1)throw RuntimeError(name+" expects one value");auto v=eval(e->args[0]);auto o=std::get_if<Value::Object>(&v.data);if(!o)throw RuntimeError("Option value expected");auto it=o->find("tag");if(it==o->end())throw RuntimeError("invalid Option value");return Value(it->second.str()==(name=="is_some"?"some":"none"));}if(name=="unwrap_or"){if(e->args.size()!=2)throw RuntimeError("unwrap_or expects two arguments");auto v=eval(e->args[0]);auto o=std::get_if<Value::Object>(&v.data);if(!o)throw RuntimeError("Option value expected");auto it=o->find("tag");if(it!=o->end()&&it->second.str()=="some")return(*o)["value"];return eval(e->args[1]);}if(name=="web_write"){if(e->args.size()!=2)throw RuntimeError("web_write(path, content) expects 2 arguments");auto path=eval(e->args[0]).str();auto content=eval(e->args[1]).str();std::filesystem::path out=std::filesystem::path("dist")/path;if(out.string().find("..")!=std::string::npos)throw RuntimeError("web_write path may not escape dist");std::filesystem::create_directories(out.parent_path());std::ofstream f(out,std::ios::binary);if(!f)throw RuntimeError("cannot write web file '"+out.string()+"'");f<<content;return Value{};}if(auto st=structs.find(name);st!=structs.end()){if(st->second.fields.size()!=e->args.size())throw RuntimeError("wrong struct argument count");Value::Object o;for(size_t j=0;j<e->args.size();++j)o[st->second.fields[j]]=eval(e->args[j]);return Value(std::move(o));}if(find_class(name))return make_instance(name,e->args);auto it=functions.find(name);if(it==functions.end())throw RuntimeError("undefined function '"+name+"'");if(it->second.params.size()!=e->args.size())throw RuntimeError("wrong argument count for '"+name+"'");scopes.push_back({});for(size_t j=0;j<e->args.size();++j)scopes.back()[it->second.params[j]]={eval(e->args[j]),true};returning=false;return_value={};exec_all(it->second.body);auto r=return_value;returning=false;scopes.pop_back();return r;}}throw RuntimeError("invalid expression");}
void Interpreter::exec(const StmtPtr&s){if(returning||breaking||continuing)return;if(s->kind==Stmt::Throw)throw RuntimeError(eval(s->expr).str());if(s->kind==Stmt::Try){try{exec_all(s->body);}catch(const std::exception&e){if(!s->catch_body.empty()){scopes.push_back({});if(!s->catch_name.empty())scopes.back()[s->catch_name]={std::string(e.what()),true};exec_all(s->catch_body);scopes.pop_back();}else{if(!s->finally_body.empty())exec_all(s->finally_body);throw;}}if(!s->finally_body.empty())exec_all(s->finally_body);return;}if(s->kind==Stmt::WebFile){std::filesystem::path relative=s->web_path;if(relative.is_absolute()||s->web_path.empty()||s->web_path.find("..")!=std::string::npos)throw RuntimeError("webfile path must be a non-empty relative path inside dist");auto out=std::filesystem::path("dist")/relative;std::filesystem::create_directories(out.parent_path());std::ofstream f(out,std::ios::binary);if(!f)throw RuntimeError("cannot write web file '"+out.string()+"'");for(const auto&part:s->web_parts)f<<eval(part).str();return;}switch(s->kind){case Stmt::Struct:structs[s->name]={s->fields};break;case Stmt::Class:{ClassDef d;d.parent=s->parent_name;d.fields=s->fields;for(const auto&m:s->methods){if(d.methods.count(m->name))throw RuntimeError("duplicate method '"+m->name+"' in class '"+s->name+"'");if(m->override_method&&!d.parent.empty()&&!find_method(d.parent,m->name))throw RuntimeError("method '"+m->name+"' marked override but no parent method exists");d.methods[m->name]={m->params,m->function_body};}if(!d.parent.empty()&&!find_class(d.parent))throw RuntimeError("unknown parent class '"+d.parent+"'");classes[s->name]=std::move(d);break;}case Stmt::Enum:{Value::Object values;for(const auto&v:s->enum_values)values[v]=Value(s->name+"."+v);if(scopes.back().count(s->name))throw RuntimeError("binding already exists: "+s->name);scopes.back()[s->name]={Value(std::move(values)),false};enums[s->name]={s->enum_values};break;}case Stmt::Match:{auto target=eval(s->match_expr);bool matched=false;for(const auto&branch:s->match_cases){if(binary("==",target,eval(branch.first)).truthy()){exec_all(branch.second);matched=true;break;}}if(!matched&&!s->match_default.empty())exec_all(s->match_default);break;}case Stmt::Let:if(scopes.back().count(s->name))throw RuntimeError("binding already exists: "+s->name);scopes.back()[s->name]={eval(s->expr),s->mutable_binding};break;case Stmt::Assign:{if(s->target&&s->target->kind==Expr::Member){auto obj=eval(s->target->object);auto o=std::get_if<Value::Object>(&obj.data);if(!o)throw RuntimeError("member assignment requires an object");if(s->target->object->kind!=Expr::Variable)throw RuntimeError("member assignment target must be a variable");auto b=find(s->target->object->name);if(!b)throw RuntimeError("undefined object");auto bo=std::get_if<Value::Object>(&b->value.data);if(!bo)throw RuntimeError("member assignment requires an object");(*bo)[s->target->name]=eval(s->expr);break;}auto b=find(s->name);if(!b)throw RuntimeError("undefined variable '"+s->name+"'");if(!b->mutable_binding)throw RuntimeError("cannot assign to immutable binding '"+s->name+"'");b->value=eval(s->expr);break;}case Stmt::Print:{for(size_t j=0;j<s->print_args.size();++j){if(j)std::cout<<' ';std::cout<<eval(s->print_args[j]).str();}std::cout<<'\n';break;}case Stmt::ExprStmt:eval(s->expr);break;case Stmt::Function:functions[s->name]={s->params,s->function_body};break;case Stmt::Return:return_value=s->expr?eval(s->expr):Value{};returning=true;break;case Stmt::Break:breaking=true;break;case Stmt::Continue:continuing=true;break;case Stmt::If:{for(auto&b:s->branches)if(eval(b.first).truthy()){exec_all(b.second);return;}exec_all(s->else_body);break;}case Stmt::While:while(eval(s->expr).truthy()){exec_all(s->body);if(returning)break;if(breaking){breaking=false;break;}if(continuing){continuing=false;continue;}}break;case Stmt::For:{auto a=eval(s->for_start),b=eval(s->for_end);auto x=std::get_if<std::int64_t>(&a.data),y=std::get_if<std::int64_t>(&b.data);if(!x||!y)throw RuntimeError("for range requires int bounds");scopes.push_back({});scopes.back()[s->name]={Value(*x),true};for(std::int64_t n=*x;n<=*y;++n){scopes.back()[s->name].value=Value(n);exec_all(s->body);if(returning)break;if(breaking){breaking=false;break;}if(continuing)continuing=false;}scopes.pop_back();break;}default:throw RuntimeError("unsupported statement");}}
void Interpreter::exec_all(const std::vector<StmtPtr>&b){for(auto&s:b){exec(s);if(returning||breaking||continuing)break;}}
void Interpreter::run(const Program&p){scopes.clear();functions.clear();structs.clear();enums.clear();classes.clear();returning=breaking=continuing=false;scopes.push_back({});exec_all(p.statements);}
}